<?php include "../auth/cek_login.php";include "../koneksi.php";if($_SESSION['role']!='admin')die('Akses ditolak');$id=$_GET['id'];$d=mysqli_fetch_assoc(mysqli_query($conn,"SELECT * FROM users WHERE id=$id"));if(isset($_POST['update'])){ $pw=$_POST['password']; $set="username='$_POST[username]',nama='$_POST[nama]',role='$_POST[role]'";if($pw!='')$set.=",password=MD5('$pw')";mysqli_query($conn,"UPDATE users SET $set WHERE id=$id");header("Location:index.php");exit;}?><!doctype html><html><head><title>Edit User</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="content"><h1>Edit User</h1><form method="post"><input name="username" value="<?=$d['username']?>" required><input type="password" name="password" placeholder="Kosongkan jika tidak ganti"><input name="nama" value="<?=$d['nama']?>" required><select name="role"><option <?=$d['role']=='petugas'?'selected':''?>>petugas</option><option <?=$d['role']=='admin'?'selected':''?>>admin</option></select><button name="update">Update</button></form></div></body></html>